import * as THREE from 'three/webgpu';
import { texture, mul, add, attribute } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(1.25, -0.2, 0);
  group.scale.set(1, 1, 1);
  group.userData.handlers = {};

  const timelines = [];

  // Load textures via context (cached)
  const imageTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthMapTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');

  // Tessellated plane for smooth displacement
  const geometry = new THREE.PlaneGeometry(1, 0.625, 64, 64);

  // TSL displacement mapping
  const depthSample = texture(depthMapTexture).r;
  const displacementScale = 0.08;
  const displacementAmount = mul(depthSample, displacementScale);
  const displacedPosition = add(
    attribute('position'),
    mul(attribute('normal'), displacementAmount)
  );

  // Machined-metal PBR material
  const material = new THREE.MeshStandardNodeMaterial({
    colorNode: texture(imageTexture),
    metalness: 0.45,
    roughness: 0.6,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    positionNode: displacedPosition,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  group.add(mesh);

  // Apply cinematic primitives
  if (ctx.primitives) {
    if (typeof ctx.primitives['parallax-scroll'] === 'function') {
      ctx.primitives['parallax-scroll'](mesh, { intensity: 0.4 });
    }
    if (typeof ctx.primitives['depth-rotate'] === 'function') {
      ctx.primitives['depth-rotate'](mesh, { maxDeg: 8 });
    }
  }

  // Hover handler: rise-in effect (0.15 scene units)
  group.userData.handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: -0.05,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  // Unhover handler: return to original position
  group.userData.handlers.unhover = () => {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: -0.2,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  // Click handler: press-down effect + emit event
  group.userData.handlers.click = () => {
    const tl = gsap.timeline();
    tl.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    }, 0);
    tl.to(mesh.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out',
    }, 0.12);
    timelines.push(tl);

    // Emit navigation event
    if (config.eventEmitter && typeof config.eventEmitter.emit === 'function') {
      config.eventEmitter.emit('hub-pricing.select', {
        nodeId: config.id,
        timestamp: Date.now(),
      });
    }
  };

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    depthMapTexture.dispose();
  };

  return group;
}
